    COALESCE(bvc.factory_0_100_s, bv.factory_0_100_s) AS factory_0_100_s,
    COALESCE(bvc.drivetrain_loss_pct, bv.drivetrain_loss_pct) AS drivetrain_loss_pct,
    bv.top_speed_kmh,
    bv.top_speed_mph,
    bv.transmission_type AS variant_transmission_type,
    bv.gear_count AS variant_gear_count,
    bv.drivetrain_layout AS variant_drivetrain_layout,
    bv.drivetrain_label AS variant_drivetrain_label,
    bvc.id AS configuration_id,
    bvc.body_style_id,
    bs.code AS body_style_code,
    bs.name AS body_style_name,
    bvc.transmission_type AS configuration_transmission_type,
    bvc.gear_count AS configuration_gear_count,
    bvc.drivetrain_layout AS configuration_drivetrain_layout,
    bvc.drivetrain_label AS configuration_drivetrain_label,
    bvc.front_suspension_type,
    bvc.rear_suspension_type,
    bvc.created_at AS configuration_created_at,
    diff.differential_type,
    diff.differential_label,
    diff.differential_source,
    diff.is_default AS differential_is_default
   FROM ((((((brands b
     JOIN models m ON ((m.brand_id = b.id)))
     JOIN generations g ON ((g.model_id = m.id)))
     JOIN bmw_variants bv ON ((bv.generation_id = g.id)))
     LEFT JOIN bmw_variant_configurations bvc ON ((bvc.variant_id = bv.id)))
     LEFT JOIN body_styles bs ON ((bs.id = bvc.body_style_id)))
     LEFT JOIN LATERAL ( SELECT d.differential_type,
            d.differential_label,
            d.differential_source,
            d.is_default
           FROM bmw_configuration_differentials d
          WHERE (d.configuration_id = bvc.id)
          ORDER BY d.is_default DESC, d.id
         LIMIT 1) diff ON (true))$source$;
